    // Hold read mux address to guarantee it is stable throughout any external accesses
    always_ff @(posedge clk or negedge arst_n) begin
        if(~arst_n) begin
            pending_rd_addr <= '0;
        end else begin
            if(decoded_req) pending_rd_addr <= decoded_addr;
        end
    end
    assign rd_mux_addr = decoded_req ? decoded_addr : pending_rd_addr;

    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_data_var = '0;
        if(rd_mux_addr == 7'h0) begin
            readback_data_var[0] = field_storage.INTR_STATE.edn_cmd_req_done.value;
            readback_data_var[1] = field_storage.INTR_STATE.edn_fatal_err.value;
        end
        if(rd_mux_addr == 7'h4) begin
            readback_data_var[0] = field_storage.INTR_ENABLE.edn_cmd_req_done.value;
            readback_data_var[1] = field_storage.INTR_ENABLE.edn_fatal_err.value;
        end
        if(rd_mux_addr == 7'h10) begin
            readback_data_var[0] = field_storage.REGWEN.REGWEN.value;
        end
        if(rd_mux_addr == 7'h14) begin
            readback_data_var[3:0] = field_storage.CTRL.EDN_ENABLE.value;
            readback_data_var[7:4] = field_storage.CTRL.BOOT_REQ_MODE.value;
            readback_data_var[11:8] = field_storage.CTRL.AUTO_REQ_MODE.value;
            readback_data_var[15:12] = field_storage.CTRL.CMD_FIFO_RST.value;
        end
        if(rd_mux_addr == 7'h18) begin
            readback_data_var[31:0] = field_storage.BOOT_INS_CMD.BOOT_INS_CMD.value;
        end
        if(rd_mux_addr == 7'h1c) begin
            readback_data_var[31:0] = field_storage.BOOT_GEN_CMD.BOOT_GEN_CMD.value;
        end
        if(rd_mux_addr == 7'h24) begin
            readback_data_var[0] = hwif_in.SW_CMD_STS.CMD_REG_RDY.next;
            readback_data_var[1] = hwif_in.SW_CMD_STS.CMD_RDY.next;
            readback_data_var[2] = hwif_in.SW_CMD_STS.CMD_ACK.next;
            readback_data_var[5:3] = hwif_in.SW_CMD_STS.CMD_STS.next;
        end
        if(rd_mux_addr == 7'h28) begin
            readback_data_var[0] = hwif_in.HW_CMD_STS.BOOT_MODE.next;
            readback_data_var[1] = hwif_in.HW_CMD_STS.AUTO_MODE.next;
            readback_data_var[5:2] = hwif_in.HW_CMD_STS.CMD_TYPE.next;
            readback_data_var[6] = hwif_in.HW_CMD_STS.CMD_ACK.next;
            readback_data_var[9:7] = hwif_in.HW_CMD_STS.CMD_STS.next;
        end
        if(rd_mux_addr == 7'h34) begin
            readback_data_var[31:0] = field_storage.MAX_NUM_REQS_BETWEEN_RESEEDS.MAX_NUM_REQS_BETWEEN_RESEEDS.value;
        end
        if(rd_mux_addr == 7'h38) begin
            readback_data_var[0] = field_storage.RECOV_ALERT_STS.EDN_ENABLE_FIELD_ALERT.value;
            readback_data_var[1] = field_storage.RECOV_ALERT_STS.BOOT_REQ_MODE_FIELD_ALERT.value;
            readback_data_var[2] = field_storage.RECOV_ALERT_STS.AUTO_REQ_MODE_FIELD_ALERT.value;
            readback_data_var[3] = field_storage.RECOV_ALERT_STS.CMD_FIFO_RST_FIELD_ALERT.value;
            readback_data_var[12] = field_storage.RECOV_ALERT_STS.EDN_BUS_CMP_ALERT.value;
            readback_data_var[13] = field_storage.RECOV_ALERT_STS.CSRNG_ACK_ERR.value;
        end
        if(rd_mux_addr == 7'h3c) begin
            readback_data_var[0] = hwif_in.ERR_CODE.SFIFO_RESCMD_ERR.next;
            readback_data_var[1] = hwif_in.ERR_CODE.SFIFO_GENCMD_ERR.next;
            readback_data_var[20] = hwif_in.ERR_CODE.EDN_ACK_SM_ERR.next;
            readback_data_var[21] = hwif_in.ERR_CODE.EDN_MAIN_SM_ERR.next;
            readback_data_var[22] = hwif_in.ERR_CODE.EDN_CNTR_ERR.next;
            readback_data_var[28] = hwif_in.ERR_CODE.FIFO_WRITE_ERR.next;
            readback_data_var[29] = hwif_in.ERR_CODE.FIFO_READ_ERR.next;
            readback_data_var[30] = hwif_in.ERR_CODE.FIFO_STATE_ERR.next;
        end
        if(rd_mux_addr == 7'h40) begin
            readback_data_var[4:0] = field_storage.ERR_CODE_TEST.ERR_CODE_TEST.value;
        end
        if(rd_mux_addr == 7'h44) begin
            readback_data_var[8:0] = hwif_in.MAIN_SM_STATE.MAIN_SM_STATE.next;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr & ~decoded_req_is_external;
        readback_err = '0;
    end

    assign external_rd_ack = readback_external_rd_ack;
    assign cpuif_rd_ack = readback_done | readback_external_rd_ack;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
